effect.shader:
const int CAMADAS = 6;

float h2(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

/** A largura do quadro, em pixels do buffer: é a régua do plugin. */
float largura() { return acResolution.x; }
/** A linha da gota tem ~1 px da COMPOSIÇÃO em qualquer resolução (σ 0,46: a energia medida de um risco). */
float sigmaDaLinha() { return 0.46 * acEscalaDePixel; }
/** O Blur cresce com a largura, mas devagar (medido em 640, 1280 e 1618: (L/640)^0,72). */
float sigmaDoBlur() {
    return blur * (0.7 + 0.42 * exp(-blur / 2.5)) * pow(largura() / (640.0 * acEscalaDePixel), 0.72) * acEscalaDePixel;
}

/** Uma camada de riscos paralelos: (brilho × opacidade, opacidade) no pixel. */
vec2 camada(vec2 px, float n) {
    float L = largura();
    float sem = randomSeed * 0.713 + n * 37.0;
    // Direction Variance: ±valor/2,7 graus (desvio medido 3,2° / 8,6° / 16,5° com 15 / 45 / 90), uma fatia por camada.
    float fatia = ((n + h2(vec2(n, sem + 3.0))) / float(CAMADAS)) * 2.0 - 1.0;
    float ang = radians(rainAngle + directionVariance / 2.7 * fatia);
    vec2 d = vec2(sin(ang), cos(ang));                 // para onde a gota cai
    vec2 o = vec2(d.y, -d.x);
    float ao = dot(px, d), at = dot(px, o);

    float fatorDeTamanho = size < 0.0 ? 1.0 + size / 100.0 : pow(1.0 + size / 100.0, 4.2);
    float passo = rainSpeed * L / 3360.0;              // pixels por quadro de 1/30 s
    // 6 × Amount gotas por quadro 16:9 (= 10,67 × Amount por L²) com a velocidade de fábrica. O que
    // é fixo é quantas NASCEM por segundo: mais rápidas, menos gotas no quadro ao mesmo tempo.
    float densidade = 10.67 * rainAmount * min(120.0 / max(tileWidth, 1.0), 1.15) * 300.0 / max(rainSpeed, 10.0) / (L * L);
    // Chuva inclinada demora mais para cruzar o quadro: mais gotas à vista (medido em 45° e 75°).
    densidade *= pow(max(cos(radians(rainAngle)), 0.05), -0.8) / pow(cos(radians(15.0)), -0.8);
    float periodo = max(0.25 * L, 1.6 * passo * 1.6 * fatorDeTamanho);
    float faixa = 0.02 * L;
    float p = densidade * faixa * periodo / float(CAMADAS);
    if (p > 1.0) { faixa = max(faixa / p, 2.0 * acEscalaDePixel); p = 1.0; }

    vec2 soma = vec2(0.0);
    float s0 = sigmaDaLinha();
    for (int k = -1; k <= 1; k++) {
        float f = floor(at / faixa) + float(k);
        float u = h2(vec2(f, sem));
        // Profundidade: perto = mais rápido e comprido; Speed Variance: até 80% mais lento.
        float escala = 1.0 / (1.0 + rainDepth / 200.0 * (-0.28 + 0.6 * pow(u, 0.75)));
        float variacao = max(1.0 + speedVariance / 200.0 * (-0.9 + 1.1 * h2(vec2(f, sem + 5.0))), 0.05);
        escala *= variacao;
        float vel = passo * escala * 30.0;             // px/s
        float comp = max(passo * escala * fatorDeTamanho, 0.0) + 1.2 * acEscalaDePixel;
        float s = ao - vel * acTime + h2(vec2(f, sem + 9.0)) * periodo;
        float c = floor(s / periodo);
        if (h2(vec2(f * 1.31 + c * 7.77, sem + c)) >= p / sqrt(variacao)) continue;   // as lentas ficam mais tempo no quadro
        float centro = (c + 0.5) * periodo + (h2(vec2(c, f + sem)) - 0.5) * max(periodo - comp, 0.0);
        float t = (s - centro) / (0.5 * comp);         // −1 = a ponta de cima, +1 = a de baixo
        float bordaPx = (1.0 - abs(t)) * 0.5 * comp;
        if (bordaPx <= -1.0) continue;
        float aoLongo = dropShape == 0 ? clamp(bordaPx + 0.5, 0.0, 1.0) : clamp(1.0 - abs(t), 0.0, 1.0);
        float x = at - (f + 0.5 + (h2(vec2(f, c + sem + 2.0)) - 0.5) * 0.7) * faixa;
        float perfil = exp(-0.5 * x * x / (s0 * s0)) * aoLongo;
        float brilho = 1.0 - clamp(-brightnessVariance, 0.0, 100.0) / 100.0 * h2(vec2(c + 0.5, f + sem));
        soma = max(soma, perfil * vec2(brilho, 1.0));
    }
    return soma;
}

vec4 borrar(bool deChuva, vec2 eixo) {
    float sigma = sigmaDoBlur();
    vec2 uv = acScreenNorm;
    if (sigma < 0.05) return deChuva ? texture(chuva, uv) : texture(bh, uv);
    float passo = max(1.0, ceil(3.0 * sigma / 20.0));
    vec4 soma = vec4(0.0);
    float pesos = 0.0;
    for (int n = -20; n <= 20; n++) {
        float dd = float(n) * passo;
        if (abs(dd) > 3.0 * sigma + 0.5) continue;
        float w = exp(-0.5 * dd * dd / (sigma * sigma));
        vec2 q = uv + eixo * dd * acTexelSize;
        soma += w * (deChuva ? texture(chuva, q) : texture(bh, q));
        pesos += w;
    }
    return soma / max(pesos, 1e-6);
}

void main() {
    vec2 uv = acScreenNorm;
    if (acPass == 0) {
        vec2 px = (uv - (panXY - vec2(0.5, 1.0))) * acResolution;
        // As gotas nascem ~0,17·L acima do quadro e vivem `lifespan` quadros de queda.
        float alcance = -0.17 * largura() + rainSpeed * largura() / 3360.0 * lifespan * cos(radians(rainAngle));
        vec2 soma = vec2(0.0);
        if (rainAmount > 0.0 && rainSpeed > 0.0 && px.y < alcance) {
            for (int n = 0; n < CAMADAS; n++) {
                vec2 c = camada(px, float(n));
                soma = soma + c * (1.0 - soma.y);       // uma gota por cima da outra
            }
        }
        // Guardado com folga: o borrão espalha, e o pico de uma linha de 1 px cabe em 8 bits.
        fragColor = vec4(soma.x, 0.0, 0.0, soma.y);
        return;
    }
    if (acPass == 1) { fragColor = borrar(true, vec2(1.0, 0.0)); return; }
    if (acPass == 2) { fragColor = borrar(false, vec2(0.0, 1.0)); return; }

    vec4 fonte = texture(inputImg, uv);
    vec4 g = texture(bv, uv);
    float op = pow(clamp(opacity / 100.0, 0.0, 1.0), 0.77);
    float a = clamp(g.a * op, 0.0, 1.0);
    fragColor = vec4(clamp(fonte.rgb * (1.0 - a) + color.rgb * g.r * op, 0.0, 1.0), fonte.a);
}
